import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.1R7PBCUH.js";const i="/computer-fundamentals/assets/firefox.C-6CFGts.png",r="/computer-fundamentals/assets/files.Do5OOUED.png",n="/computer-fundamentals/assets/app_center.BwZt_3Iv.png",c="/computer-fundamentals/assets/settings.Cnro1JOC.png",g=JSON.parse('{"title":"Exercises 1","description":"","frontmatter":{},"headers":[],"relativePath":"exercises/exercises1.md","filePath":"exercises/exercises1.md"}'),l={name:"exercises/exercises1.md"};function p(h,e,d,u,m,f){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="exercises-1" tabindex="-1">Exercises 1 <a class="header-anchor" href="#exercises-1" aria-label="Permalink to &quot;Exercises 1&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>These exercises are still in draft. The text isn&#39;t polished yet and new exercises may be added in the future.</p></div><p>In these exercises, you&#39;ll continue exploring Ubuntu. You&#39;ll try out a few apps, install new software, and customize the desktop to your preferences.</p><h2 id="firefox" tabindex="-1">Exercise 1.1 <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Exercise 1.1 {#firefox}&quot;">​</a></h2><p>Open the Firefox web browser:</p><p><img src="'+i+'" alt="Firefox"></p><p>Navigate to the page you&#39;re on now, <a href="../lab-materials.zip">download the lab materials for this course</a>, and save this file to your <strong>Downloads</strong> directory. Continue browsing the web, download a few more files, and bookmark some of your favorite sites.</p><p>Next, open Firefox settings. Configure your home screen and set your search engine to something other than Google, such as <a href="https://duckduckgo.com" target="_blank" rel="noreferrer">DuckDuckGo</a> or <a href="https://www.ecosia.org" target="_blank" rel="noreferrer">Ecosia</a>.</p><p>Finally, if you&#39;re interested in using Firefox on your host system as well, you can create an account to synchronize your bookmarks and settings between devices.</p><h2 id="exercise-1-2" tabindex="-1">Exercise 1.2 <a class="header-anchor" href="#exercise-1-2" aria-label="Permalink to &quot;Exercise 1.2&quot;">​</a></h2><p>Open the Files app:</p><p><img src="'+r+'" alt="Files"></p><p>Familiarize yourself with this app as you explore your home directory. Verify that your <strong>Downloads</strong> directory contains the files you downloaded in the previous exercise.</p><h2 id="exercise-1-3" tabindex="-1">Exercise 1.3 <a class="header-anchor" href="#exercise-1-3" aria-label="Permalink to &quot;Exercise 1.3&quot;">​</a></h2><p>Open App Center:</p><p><img src="'+n+'" alt="App Center"></p><p>Explore its offerings and download an application that you know or would like to try. Pin this application to your dock.</p><h2 id="exercise-1-4" tabindex="-1">Exercise 1.4 <a class="header-anchor" href="#exercise-1-4" aria-label="Permalink to &quot;Exercise 1.4&quot;">​</a></h2><p>Open the Settings app:</p><p><img src="'+c+`" alt="Settings"></p><p>Perform the following tasks:</p><ul><li>Adjust your display resolution and scale to something that works well for your virtual machine.</li><li>Try out the dark appearance. Switch back to the default appearance if you prefer that.</li><li>Pick an accent color.</li><li>Set a background image for your desktop.</li><li>Adjust the size and position of the dock to your liking.</li><li>Turn off Automatic Screen Lock. You don&#39;t need this in a virtual machine.</li></ul><h2 id="exercise-1-4-1" tabindex="-1">Exercise 1.4 <a class="header-anchor" href="#exercise-1-4-1" aria-label="Permalink to &quot;Exercise 1.4&quot;">​</a></h2><p>Use the Settings app to add an additional user account. Use the Quick Settings panel to switch to this account, then back to yours. Remove the account when you&#39;re done.</p><h2 id="exercise-1-5" tabindex="-1">Exercise 1.5 <a class="header-anchor" href="#exercise-1-5" aria-label="Permalink to &quot;Exercise 1.5&quot;">​</a></h2><p>Open a terminal and run the following commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whoami</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span></span></code></pre></div><p>What do these commands have in common?</p><details><summary>Solution</summary> They all show part of the information that makes up the default prompt: your username, the hostname of your machine, and the current directory. </details>`,29)])])}const k=a(l,[["render",p]]);export{g as __pageData,k as default};
